ct_cols <- c("Epithelial (malignant)" = "#6BAED6", "Acinar" = "#B5B5B5", "Fibroblast/CAF" = "#D8A56B", "Endothelial" = "#E3C34D", "Myeloid" = "#5C9E6B", "Mast" = "#A3C4A0", "T/NK" = "#9A9AD6", "B/Plasma" = "#E58AA0")
umap_axes <- function(d) { x0 <- min(d$UMAP1); y0 <- min(d$UMAP2); rx <- diff(range(d$UMAP1)); ry <- diff(range(d$UMAP2)); l <- 0.14
  list(annotate("segment", x = x0, xend = x0 + l * rx, y = y0, yend = y0, linewidth = 0.3, arrow = arrow(length = unit(0.8, "mm"), type = "closed")), annotate("segment", x = x0, xend = x0, y = y0, yend = y0 + l * ry * 1.6, linewidth = 0.3, arrow = arrow(length = unit(0.8, "mm"), type = "closed")),
       annotate("text", x = x0 + l * rx / 2, y = y0 - 0.035 * ry, label = "UMAP1", size = 4 / pp, family = fam, vjust = 1), annotate("text", x = x0 - 0.02 * rx, y = y0 + l * ry * 0.8, label = "UMAP2", size = 4 / pp, family = fam, angle = 90, vjust = 0)) }
